on conflict (club_id, provider, external_event_id) where external_event_id is not null
do update set
  match_date   = excluded.match_date,
  kickoff_time = excluded.kickoff_time,
  competition  = excluded.competition,
  is_home      = excluded.is_home,
  sport_status = excluded.sport_status,
  -- Le lieu ne vient que de la fenetre glissante de la source : on ne l'efface pas quand elle ne
  -- le donne plus, sinon chaque synchro viderait les lieux des matchs passes.
  lieu         = coalesce(excluded.lieu, public.club_matches.lieu),
  team_id      = coalesce(public.club_matches.team_id, excluded.team_id),
  last_synced_at = now();
